ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, category = EXCLUDED.category, collection = EXCLUDED.collection,
  description = EXCLUDED.description, price_cents = EXCLUDED.price_cents, visual = EXCLUDED.visual,
  material = EXCLUDED.material, ritual = EXCLUDED.ritual, best_used_when = EXCLUDED.best_used_when,
  details = EXCLUDED.details, dimensions = EXCLUDED.dimensions, care = EXCLUDED.care,
  stock = EXCLUDED.stock, featured = EXCLUDED.featured, kind = EXCLUDED.kind, active = TRUE, updated_at = NOW();

ON CONFLICT (id) DO UPDATE SET url = EXCLUDED.url, alt = EXCLUDED.alt, role = EXCLUDED.role, width = EXCLUDED.width, height = EXCLUDED.height, sort_order = EXCLUDED.sort_order;
